import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { useService } from "../services/useService";

function DetalleProducto() {

  const { id } = useParams();

  const [producto, setProducto] = useState(null);
  const [mensaje, setMensaje] = useState("");

  const nombresAbarrotes = {
    1: "Arroz Costeño",
    2: "Aceite Primor",
    3: "Azúcar Rubia",
    4: "Leche Gloria",
    5: "Fideos Don Vittorio",
    6: "Atún Florida",
    7: "Galletas Soda",
    8: "Avena Quaker",
    9: "Café Altomayo",
    10: "Harina Blanca Flor"
  };

  useEffect(() => {

    async function cargarProducto() {

      const data = await useService.getProductById(id);

      setProducto(data);

    }

    cargarProducto();

  }, [id]);

  const agregarCarrito = () => {
    setMensaje("✅ Producto agregado al carrito");
  };

  if (!producto) {
    return <h2>Cargando producto...</h2>;
  }

  return (
    <div>

      <h2>Detalle del Producto</h2>

      <h3>{nombresAbarrotes[id]}</h3>

      <p>Precio: S/ {producto.price}</p>

      <p>Stock: 20 unidades</p>

      <p>Categoría: Abarrotes</p>

      <p>
        Producto disponible para compra en TiendaClick.
      </p>

      <button onClick={agregarCarrito}>
        Agregar al carrito
      </button>

      <p>{mensaje}</p>

    </div>
  );
}

export default DetalleProducto;
